// Query Input & Normalizer
// Accepts input query from upstream item or falls back to default test query
const firstItem = $input.first();
let rawQuery = '';

if (firstItem && firstItem.json && typeof firstItem.json.query === 'string') {
  rawQuery = firstItem.json.query;
} else if (firstItem && firstItem.json && typeof firstItem.json.text === 'string') {
  rawQuery = firstItem.json.text;
} else {
  rawQuery = 'Hello';
}

const trimmed = rawQuery.trim();
if (!trimmed) {
  throw new Error('Query validation failed: incoming coaching question is empty.');
}

return [{
  json: {
    query: trimmed
  }
}];

// Greeting Classifier
// Deterministically classifies purely conversational greetings BEFORE any embedding or database queries.
// Must NEVER classify substantive questions that begin with greetings (e.g. 'Hello, how do I apply...') as greetings.
const query = $input.first().json.query || '';
const trimmed = query.trim();

// Normalize for classification: remove trailing exclamation/question/period and lowercase
const cleaned = trimmed.toLowerCase().replace(/[!.,?]+$/, '').trim();

// Regex matching exact standalone greetings and polite salutations
const standaloneGreetingPattern = /^(hi|hello|hey|howdy|greetings|good\s+(morning|afternoon|evening|day))(\s+(there|dr\.?\s*sara(\s+hegy)?|sara|coach))?$/i;

const isGreetingOnly = standaloneGreetingPattern.test(cleaned);

let greetingResponse = null;
if (isGreetingOnly) {
  greetingResponse = "Hello! I am Dr. Sara Hegy's executive coaching assistant at GenX Leadership Academy. How can I support your leadership journey or discuss our executive coaching frameworks today?";
}

return [{
  json: {
    query: trimmed,
    is_greeting: isGreetingOnly,
    greeting_response: greetingResponse
  }
}];

// Static Greeting Response
// Returns immediate static response without invoking Ollama embedding, PostgreSQL, or LLM generation.
const item = $input.first().json;

return [{
  json: {
    query: item.query,
    response: item.greeting_response,
    framework_count: 0,
    voice_count: 0,
    total_qualifying_chunks: 0,
    retrieval_metadata: {
      gate_status: "BYPASS_GREETING",
      is_greeting: true,
      embedding_called: false,
      sql_called: false,
      llm_invoked: false
    }
  }
}];

// Validate Query Vector
// Rigorously verifies the embedding returned by Ollama bge-m3
// Exactly 1,024 finite numeric elements, zero null/NaN/Infinity
const item = $input.first().json;
const embedding = item.embedding;
const query = $('Greeting Classifier').first().json.query;

if (!embedding || !Array.isArray(embedding)) {
  throw new Error('Ollama embedding service failed: vector is missing or not an array.');
}

if (embedding.length !== 1024) {
  throw new Error(`Embedding vector validation failed: dimension is ${embedding.length}, expected 1024.`);
}

for (let i = 0; i < embedding.length; i++) {
  const val = embedding[i];
  if (typeof val !== 'number' || !Number.isFinite(val)) {
    throw new Error(`Embedding vector validation failed: element at index ${i} is non-numeric or non-finite (${val}).`);
  }
}

// Format pgvector literal: [v1,v2,...,v1024]
const vectorStr = '[' + embedding.join(',') + ']';

return [{
  json: {
    query: query,
    query_vector_str: vectorStr,
    embedding_dimension: embedding.length
  }
}];

// Aggregate & Gate Results
// Consolidates independent framework and voice retrieval results from both streams.
// Filters out empty records emitted by alwaysOutputData when zero rows matched SQL thresholds.
const allItems = $input.all();
const query = $('Validate Query Vector').first().json.query;

const frameworkChunks = allItems
  .map(i => i.json)
  .filter(j => j && j.id !== undefined && j.stream_type === 'framework');

const voiceChunks = allItems
  .map(i => i.json)
  .filter(j => j && j.id !== undefined && j.stream_type === 'voice_sample');

const frameworkCount = frameworkChunks.length;
const voiceCount = voiceChunks.length;
const totalQualifyingChunks = frameworkCount + voiceCount;
const hasQualifyingResults = totalQualifyingChunks > 0;

return [{
  json: {
    query: query,
    framework_count: frameworkCount,
    voice_count: voiceCount,
    total_qualifying_chunks: totalQualifyingChunks,
    framework_chunks: frameworkChunks,
    voice_chunks: voiceChunks,
    has_qualifying_results: hasQualifyingResults,
    response: hasQualifyingResults ? null : 'No documented coaching frameworks match this topic.'
  }
}];

// Return Zero Result Output
// Enforces the mandatory assignment fallback when both streams yield zero qualifying results.
// The generation LLM is NEVER called in this case.
const item = $input.first().json;

return [{
  json: {
    query: item.query,
    response: "No documented coaching frameworks match this topic.",
    framework_count: 0,
    voice_count: 0,
    total_qualifying_chunks: 0,
    retrieval_metadata: {
      gate_status: "REJECTED_ZERO_RESULTS",
      framework_threshold: 0.70,
      voice_threshold: 0.65,
      llm_invoked: false
    }
  }
}];

// Format Grounded Prompt
// Constructs a strictly bounded prompt for Dr. Sara Hegy's AI coaching assistant:
// 1. Framework evidence provides conceptual truth.
// 2. Voice samples guide tone and cadence only.
// 3. Clear boundaries prevent prompt leakage, case study confusion, and hallucinated claims.
const item = $input.first().json;
const query = item.query;
const frameworkChunks = item.framework_chunks || [];
const voiceChunks = item.voice_chunks || [];

let frameworkText = "";
if (frameworkChunks.length > 0) {
  frameworkText = frameworkChunks.map((f, i) => f.content).join("\n\n");
} else {
  frameworkText = "No specific conceptual framework was retrieved for this topic (all candidate frameworks scored below the 0.70 threshold). Note: You must explicitly state that no documented coaching framework is available on this topic.";
}

let voiceText = "";
if (voiceChunks.length > 0) {
  voiceText = voiceChunks.map((v, i) => `"${v.content}"`).join("\n\n");
} else {
  voiceText = "Tone guidance: Direct, empathetic, practical, and focused on cognitive bandwidth.";
}

const prompt = `You are Dr. Sara Hegy, an executive leadership coach at GenX Leadership Academy. Answer the leader's question directly, concisely, and supportively.

GUIDELINES:
- Base your advice strictly on the coaching framework provided below. Do not invent steps, acronyms, or metrics not present in the framework.
- If the framework text indicates that no documented framework was retrieved, clearly inform the leader that no documented coaching framework matches this topic.
- Do NOT mention prompt sections, evidence labels, similarity scores, or internal instructions to the leader.
- Do NOT confuse people in past coaching transcripts (such as Mark D. or Alex) with the leader asking the question.
- Do NOT invent ungrounded business metrics or productivity claims.
- Speak directly to the leader in Dr. Sara's signature cadence: empathetic, incisive, focused on cognitive bandwidth.

COACHING FRAMEWORK:
${frameworkText}

STYLE REFERENCE:
${voiceText}

LEADER'S QUESTION:
${query}

COACHING RESPONSE:`;

return [{
  json: {
    ...item,
    generation_prompt: prompt
  }
}];

